1	// SPDX-License-Identifier: GPL-2.0
2	/*
3	 * weaknet_lradc_keys.c - Allwinner A733 (sun60iw2p1) LRADC 按键驱动
4	 *
5	 * 定位：B1 实验路径的第二阶段——从「读内核统计量」升级到「真正操作硬件」。
6	 * 与 weaknet_cpu_stat / weaknet_softirq 不同，本驱动直接读写 MMIO 寄存器、
7	 * 注册中断、操作时钟与复位，是一个完整意义上的 platform 驱动。
8	 *
9	 * ============================================================================
10	 * 为什么不能直接复用 mainline 的 sun4i-lradc-keys.c
11	 * ============================================================================
12	 *
13	 * 1. compatible 不匹配
14	 *    mainline: "allwinner,sun4i-a10-lradc-keys" / "allwinner,sun8i-a83t-r-lradc"
15	 *    本板 DT : "allwinner,keyboard_1350mv"
16	 *    → of_match_table 永远匹配不上，驱动不会 probe。
17	 *
18	 * 2. 按键表（keymap）的 DT 表达形式完全不同
19	 *    mainline 用子节点：
20	 *        keys {
21	 *            key0 { channel = <0>; voltage = <210>; linux,code = <115>; };
22	 *        };
23	 *    本板用成对属性 + 计数：
24	 *        key0    = <210 115>;   （电压 210 mV，键码 115）
25	 *        key_cnt = <5>;
26	 *    → mainline 的 of_get_child_count() 返回 0，直接 -EINVAL。
27	 *
28	 * 3. 参考电压来源不同
29	 *    mainline: devm_regulator_get(dev, "vref") + variant 分压系数
30	 *    本板 DT : 没有 vref-supply，参考电压直接编码在 compatible 后缀
31	 *              "keyboard_1350mv" 里（1350 mV）。
32	 *    → regulator 拿不到，mainline 会 -EPROBE_DEFER 后失败。
33	 *
34	 * 4. 时钟与复位
35	 *    本板 DT 有 clocks=<0x12 0xc1> 与 resets=<0x12 0x47>，但 mainline 驱动
36	 *    完全不处理它们（A10/A83T 上这两路默认常开）。
37	 *    实测本板 lradc 时钟 enable_count=0，不显式 enable 就读不到正确值。
38	 *
39	 * 所以本驱动是**按本板 DT 契约重写**，不是移植。
40	 *
41	 * ============================================================================
42	 * 硬件事实（2026-11-05 板端实测）
43	 * ============================================================================
44	 *
45	 *   SoC        : sun60iw2p1 / allwinner,sun60i-a733
46	 *   板卡       : radxa,cubie-a7a
47	 *   内核       : 5.15.147-99btf1-a733 aarch64
48	 *   寄存器基址 : 0x02524000，长度 0x100
49	 *   中断       : DT <0 0x25 4> = SPI 0x25(37) 高电平触发，实测 /proc/interrupts 无占用
50	 *   时钟       : "lradc" 26 MHz，实测 enable_count=0（关闭）
51	 *   复位       : resets phandle 0x12/0x47
52	 *   初始寄存器 : CTRL=0x01000168 (ENABLE=0)，DATA0=DATA1=0x3f（6bit 满量程静默值）
53	 *   按键表     : key0..key4 = <电压mV, keycode>，key_cnt=5
54	 *                key0 <210,115 KEY_VOLUMEUP>   key1 <410,114 KEY_VOLUMEDOWN>
55	 *                key2 <590,139 KEY_MENU>       key3 <750, 28 KEY_ENTER>
56	 *                key4 <880,172 KEY_HOMEPAGE>
57	 *
58	 * ============================================================================
59	 * 分层实现进度
60	 * ============================================================================
61	 *
62	 *   L1 骨架    platform_driver + of_match + DT 解析 + ioremap + clk + reset   [本文件]
63	 *   L2 中断    request_irq + INTS 判源 + DATA0 读值 + 电压换算 + 写1清中断      [本文件]
64	 *   L3 子系统  input_dev 注册 + report_key + evdev open/close 省电              [本文件]
65	 *   L4 调试    debugfs 暴露寄存器与解码状态                                     [本文件]
66	 *
67	 * 四层已全部实现。对用户态的唯一正式出口是 /dev/input/eventN：
68	 * 用户态 open 该节点后 ADC 才开始转换，关闭后 ADC 停止（标准键盘省电语义）。
69	 * debugfs 里的 dev_info 与计数器仅供开发期诊断，不是产品接口。
70	 *
71	 * ============================================================================
72	 * 实测边界（务必保留，这是本驱动最重要的一条事实）
73	 * ============================================================================
74	 *
75	 * 本板（A733 BSP，内核 5.15.147-99btf1-a733）上，LRADC 的**模拟转换从未启动**：
76	 *
77	 *   CTRL 写入可读回（0x02000141 等组合全部精确回读）
78	 *   时钟 lradc 26 MHz，enable_count 0→1 ✓
79	 *   复位 deassert ✓
80	 *   INTC 写 0xffffffff 回读 0x00001f1f（5+5 位，与 mainline 位布局一致）✓
81	 *   已实现位扫描：CTRL 写全 1 回读 0xffcf7fff，实现位与 mainline sun4i 完全相同 ✓
82	 *   ── 但 ──
83	 *   INTS 恒 0x00000000，DATA0 恒 0x0000003f，IRQ 计数恒 0
84	 *   CHAN_SELECT 0/1/2/3、SAMPLE_RATE 0/1/2/3、KEY_MODE_SEL×LEVELB_VOL 全 16 组合、
85	 *   CONTINUE_TIME_SEL、FIRST_CONVERT_DLY、LEVELA_B_CNT、纯 ENABLE=1、
86	 *   vendor 复位值 0x01000168 + INTC=0x1f1f，全部零响应。
87	 *   排除 gpadc 争用（unbind sunxi-gpadc 后 LRADC 无变化）。
88	 *
89	 * 因此 L2 中断通路在本板**无法用物理按键验证**。应对方式：
90	 *   1. debugfs 的 selftest 会临时打开 CHAN0_DATA_IRQ 并等 100 ms，实测仍 0 次中断
91	 *      → 结论写入 dmesg「selftest FAILED: ISR path is dead」，这是正确结论，不是 bug；
92	 *   2. debugfs 的 raw 口允许直接注入一个 raw 值，走 wn_lradc_report_raw() 的完整
93	 *      「换算 → 匹配 → input 上报」链路，用来验证 L3 在没有硬件事件时依然正确。
94	 *
95	 * 换句话说：L1/L2/L4 的代码路径都能在本板跑，但只有 L3 可以被端到端证伪/证实。
96	 * 不夸大：**本驱动在 A733 上不能作为可用的按键输入设备**，它是技术栈练习与
97	 * 后续换平台（mainline sun4i 兼容 SoC）的适配基座。
98	 *
99	 * 寄存器与位定义来自 mainline drivers/input/keyboard/sun4i-lradc-keys.c
100	 * （GPL-2.0-or-later, Copyright (C) 2014 Hans de Goede），本板适配部分为本项目重写。
101	 */
102	
103	#include <linux/module.h>
104	#include <linux/kernel.h>
105	#include <linux/init.h>
106	#include <linux/platform_device.h>
107	#include <linux/of.h>
108	#include <linux/of_device.h>
109	#include <linux/io.h>
110	#include <linux/interrupt.h>
111	#include <linux/clk.h>
112	#include <linux/reset.h>
113	#include <linux/slab.h>
114	#include <linux/debugfs.h>
115	#include <linux/seq_file.h>
116	#include <linux/uaccess.h>
117	#include <linux/spinlock.h>
118	#include <linux/delay.h>
119	#include <linux/input.h>
120	#include <linux/string.h>	/* sysfs_streq() */
121	
122	/* ------------------------------------------------------------------ */
123	/* 寄存器布局（偏移相对 0x02524000）                                    */
124	/* ------------------------------------------------------------------ */
125	#define LRADC_CTRL		0x00
126	#define LRADC_INTC		0x04
127	#define LRADC_INTS		0x08
128	#define LRADC_DATA0		0x0c
129	#define LRADC_DATA1		0x10
130	
131	/* LRADC_CTRL 位域 */
132	#define FIRST_CONVERT_DLY(x)	((x) << 24)	/* 8 bits */
133	#define CHAN_SELECT(x)		((x) << 22)	/* 2 bits */
134	#define CONTINUE_TIME_SEL(x)	((x) << 16)	/* 4 bits */
135	#define KEY_MODE_SEL(x)		((x) << 12)	/* 2 bits */
136	#define LEVELA_B_CNT(x)		((x) << 8)	/* 4 bits */
137	#define HOLD_KEY_EN(x)		((x) << 7)
138	#define HOLD_EN(x)		((x) << 6)
139	#define LEVELB_VOL(x)		((x) << 4)	/* 2 bits */
140	#define SAMPLE_RATE(x)		((x) << 2)	/* 2 bits */
141	#define ENABLE(x)		((x) << 0)
142	
143	/* LRADC_INTC / LRADC_INTS 位域（本驱动只用通道 0） */
144	#define CHAN0_KEYUP_IRQ		BIT(4)
145	#define CHAN0_ALRDY_HOLD_IRQ	BIT(3)
146	#define CHAN0_HOLD_IRQ		BIT(2)
147	#define CHAN0_KEYDOWN_IRQ	BIT(1)
148	#define CHAN0_DATA_IRQ		BIT(0)
149	
150	/* 6 bit ADC，满量程 63 */
151	#define LRADC_DATA_MASK		0x3f
152	#define LRADC_FULL_SCALE	63
153	
154	/* 本板参考电压：compatible 后缀 "keyboard_1350mv" */
155	#define LRADC_DEFAULT_VREF_MV	1350
156	
157	/* 采样周期：SAMPLE_RATE(0) = 250 Hz / 4 ms，与 mainline 一致 */
158	#define LRADC_SAMPLE_RATE_VAL	0
159	
160	/* DT 里 key 属性的个数上限（key0..keyN） */
161	#define LRADC_MAX_KEYS		16
162	
163	/**
164	 * struct wn_lradc_key - 一个按键的 DT 描述
165	 * @voltage_mv: DT 里写的标称电压（毫伏）
166	 * @keycode:    linux,input-event-codes.h 里的 KEY_* 码
167	 * @raw:        由 voltage_mv 换算出的 6bit 期望码值（四舍五入，便于日志对照）
168	 */
169	struct wn_lradc_key {
170		u32 voltage_mv;
171		u32 keycode;
172		u32 raw;
173	};
174	
175	/**
176	 * struct wn_lradc - 驱动私有状态
177	 * @dev:        设备指针
178	 * @base:       ioremap 后的寄存器基址
179	 * @clk:        lradc 时钟
180	 * @rst:        复位控制（可选）
181	 * @irq:        中断号
182	 * @vref_mv:    参考电压
183	 * @keys:       按键表
184	 * @nr_keys:    按键个数
185	 * @lock:       保护 @cur_keycode 与统计计数（中断与 debugfs 并发访问）
186	 * @cur_keycode: 当前按下的键码，0 表示无键按下
187	 * @is_open:    ADC 是否已使能
188	 * @stat_irq:       中断总次数
189	 * @stat_keydown:   键按下事件次数
190	 * @stat_keyup:     键抬起事件次数
191	 * @stat_unknown:   中断里判不出源的次数
192	 * @stat_unmatched: 有电压但匹配不到任何键的次数
193	 * @last_raw:   最近一次读到的 DATA0 原始值
194	 * @last_mv:    最近一次换算出的电压
195	 * @dbg_dir:    debugfs 目录
196	 */
197	struct wn_lradc {
198		struct device *dev;
199		void __iomem *base;
200		struct clk *clk;
201		struct reset_control *rst;
202		int irq;
203		u32 vref_mv;
204	
205		/*
206		 * input 子系统设备。这是本驱动对用户态唯一的正式出口：
207		 * 注册后 /dev/input/eventN 出现，事件经 evdev 交给用户态。
208		 *
209		 * 注意 @is_open 的语义由它决定：input->open 回调里才使能 ADC，
210		 * input->close 回调里关闭。没有进程打开 evdev 时 ADC 不转换，
211		 * 这是键盘类驱动的标准省电模式（mainline 也是这么写的）。
212		 */
213		struct input_dev *input;
214	
215		struct wn_lradc_key keys[LRADC_MAX_KEYS];
216		u32 nr_keys;
217	
218		spinlock_t lock;
219		u32 cur_keycode;
220	
221		bool is_open;
222	
223		u64 stat_irq;
224		u64 stat_keydown;
225		u64 stat_keyup;
226		u64 stat_unknown;
227		u64 stat_unmatched;
228		u32 last_raw;
229		u32 last_mv;
230	
231		/* 最近一次「中断通路自检」的结果，见 wn_lradc_dbg_selftest_write() */
232		u64 selftest_irqs;
233		u32 selftest_raw;
234		bool selftest_done;
235	
236		struct dentry *dbg_dir;
237	};
238	
239	/* ------------------------------------------------------------------ */
240	/* 寄存器访问                                                          */
241	/* ------------------------------------------------------------------ */
242	
243	static inline u32 wn_lradc_read(struct wn_lradc *lradc, u32 reg)
244	{
245		return readl(lradc->base + reg);
246	}
247	
248	static inline void wn_lradc_write(struct wn_lradc *lradc, u32 reg, u32 val)
249	{
250		writel(val, lradc->base + reg);
251	}
252	
253	/*
254	 * 6bit 原始码 → 毫伏。
255	 * 与 mainline 的 val * vref / 63 等价，只是把顺序改成先乘后除以免整数截断。
256	 */
257	static u32 wn_lradc_raw_to_mv(struct wn_lradc *lradc, u32 raw)
258	{
259		return raw * lradc->vref_mv / LRADC_FULL_SCALE;
260	}
261	
262	/*
263	 * 在按键表里找与实测电压最接近的一项。
264	 * 返回键索引，找不到返回 -ENOENT。
265	 *
266	 * 语义与 mainline 一致：取绝对差最小者，而不是区间判定。
267	 * 这样 DT 里标的电压有偏差也不会整键失效。
268	 */
269	static int wn_lradc_match_key(struct wn_lradc *lradc, u32 mv, u32 *out_keycode)
270	{
271		u32 i, best_diff = U32_MAX;
272		int best = -ENOENT;
273	
274		for (i = 0; i < lradc->nr_keys; i++) {
275			u32 diff = abs((int)lradc->keys[i].voltage_mv - (int)mv);
276	
277			if (diff < best_diff) {
278				best_diff = diff;
279				best = (int)i;
280			}
281		}
282	
283		if (best >= 0 && out_keycode)
284			*out_keycode = lradc->keys[best].keycode;
285	
286		return best;
287	}
288	
289	/* ------------------------------------------------------------------ */
290	/* 按键上报                                                            */
291	/* ------------------------------------------------------------------ */
292	
293	/*
294	 * 把一个 6bit 原始值走完整的「换算 → 匹配 → 上报」链路。
295	 *
296	 * 抽成独立函数有两个目的：
297	 *   1. 中断路径与 debugfs 注入路径共用同一份判定逻辑，行为不会分叉；
298	 *   2. 让「硬件的 raw 值」与「上报语义」解耦——注入 raw 不改 DATA0 寄存器，
299	 *      所以即使 ADC 不转换，也能验证匹配与上报链路本身是否正确。
300	 *
301	 * 返回匹配到的键码（0 表示没匹配上）。
302	 *
303	 * 上下文约束：调用者必须已持有 @lradc->lock（本函数会改 @cur_keycode
304	 * 与统计计数），且必须能睡眠无关——本函数不睡眠，可从原子上下文调用。
305	 * 但 input_report_key() 内部会拿 input 设备自己的锁，故不能在持
306	 * @lradc->lock 时调用，因此这里采用「锁内算、锁外报」的分段写法。
307	 */
308	static u32 wn_lradc_report_raw(struct wn_lradc *lradc, u32 raw)
309	{
310		unsigned long flags;
311		u32 mv, keycode = 0;
312		int idx;
313	
314		mv = wn_lradc_raw_to_mv(lradc, raw);
315		idx = wn_lradc_match_key(lradc, mv, &keycode);
316	
317		spin_lock_irqsave(&lradc->lock, flags);
318		lradc->last_raw = raw;
319		lradc->last_mv = mv;
320		if (idx < 0) {
321			lradc->stat_unmatched++;
322			keycode = 0;
323		} else {
324			lradc->cur_keycode = keycode;
325			lradc->stat_keydown++;
326		}
327		spin_unlock_irqrestore(&lradc->lock, flags);
328	
329		if (idx < 0) {
330			dev_info(lradc->dev,
331				 "raw=%u mv=%u -> no matching key\n", raw, mv);
332			return 0;
333		}
334	
335		/* 锁外上报：input 子系统内部有自己的锁 */
336		if (lradc->input) {
337			input_report_key(lradc->input, keycode, 1);
338			input_sync(lradc->input);
339		}
340	
341		dev_info(lradc->dev, "key press code=%u (raw=%u mv=%u key#%d)\n",
342			 keycode, raw, mv, idx);
343		return keycode;
344	}
345	
346	/*
347	 * 释放当前按下的键。返回被释放的键码（0 表示本来就没有键按下）。
348	 */
349	static u32 wn_lradc_release(struct wn_lradc *lradc)
350	{
351		unsigned long flags;
352		u32 keycode;
353	
354		spin_lock_irqsave(&lradc->lock, flags);
355		keycode = lradc->cur_keycode;
356		lradc->cur_keycode = 0;
357		if (keycode)
358			lradc->stat_keyup++;
359		spin_unlock_irqrestore(&lradc->lock, flags);
360	
361		if (!keycode)
362			return 0;
363	
364		if (lradc->input) {
365			input_report_key(lradc->input, keycode, 0);
366			input_sync(lradc->input);
367		}
368		dev_info(lradc->dev, "key release code=%u\n", keycode);
369		return keycode;
370	}
371	
372	/* ------------------------------------------------------------------ */
373	/* 中断处理                                                            */
374	/* ------------------------------------------------------------------ */
375	
376	/*
377	 * 中断上下文约束（驱动开发必考点）：
378	 *   - 不能睡眠：不能调用 kmalloc(GFP_KERNEL)、mutex_lock、copy_to_user 等
379	 *   - 不能做长耗时操作
380	 *   本 handler 只做 readl/writel + 内存写，完全满足。
381	 *
382	 * 共享状态的保护：
383	 *   @cur_keycode 会被这里的「中断上下文」与 debugfs 的「进程上下文」同时读，
384	 *   所以用 spinlock 而非 mutex（mutex 不能用在中断里）。
385	 */
386	static irqreturn_t wn_lradc_irq(int irq, void *dev_id)
387	{
388		struct wn_lradc *lradc = dev_id;
389		unsigned long flags;
390		u32 ints, raw;
391		bool handled = false;
392	
393		/* 先读中断状态；判不出源就直接返回 IRQ_NONE，让内核统计 spurious */
394		ints = wn_lradc_read(lradc, LRADC_INTS);
395		if (!(ints & (CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ |
396			      CHAN0_HOLD_IRQ | CHAN0_ALRDY_HOLD_IRQ |
397			      CHAN0_DATA_IRQ))) {
398			spin_lock_irqsave(&lradc->lock, flags);
399			lradc->stat_unknown++;
400			lradc->stat_irq++;
401			spin_unlock_irqrestore(&lradc->lock, flags);
402			return IRQ_NONE;
403		}
404	
405		spin_lock_irqsave(&lradc->lock, flags);
406		lradc->stat_irq++;
407		spin_unlock_irqrestore(&lradc->lock, flags);
408	
409		/* 抬起：上报 release 并清掉缓存键码 */
410		if (ints & CHAN0_KEYUP_IRQ) {
411			wn_lradc_release(lradc);
412			handled = true;
413		}
414	
415		/*
416		 * 转换完成中断：只在 debugfs 自检期间被使能（正常运行时 INTC 里没有这一位）。
417		 * 它证明 ADC 真的在跑、ISR 真的被调用，是「无物理按键」环境下
418		 * 验证 L2 中断通路的唯一手段。
419		 */
420		if (ints & CHAN0_DATA_IRQ) {
421			raw = wn_lradc_read(lradc, LRADC_DATA0) & LRADC_DATA_MASK;
422	
423			spin_lock_irqsave(&lradc->lock, flags);
424			lradc->last_raw = raw;
425			lradc->last_mv = wn_lradc_raw_to_mv(lradc, raw);
426			if (lradc->selftest_done)
427				lradc->selftest_irqs++;
428			lradc->selftest_raw = raw;
429			spin_unlock_irqrestore(&lradc->lock, flags);
430	
431			handled = true;
432		}
433	
434		/*
435		 * 按下：只有在当前无键时才处理，避免重复触发把同一键反复上报。
436		 * HOLD / ALRDY_HOLD 类中断走同一套语义——按键一直按着时硬件会重复
437		 * 产生这两类中断，但因为 @cur_keycode 非 0，这里不会重复上报。
438		 */
439		if (ints & (CHAN0_KEYDOWN_IRQ | CHAN0_HOLD_IRQ | CHAN0_ALRDY_HOLD_IRQ)) {
440			bool idle;
441	
442			spin_lock_irqsave(&lradc->lock, flags);
443			idle = (lradc->cur_keycode == 0);
444			spin_unlock_irqrestore(&lradc->lock, flags);
445	
446			if (idle) {
447				raw = wn_lradc_read(lradc, LRADC_DATA0) & LRADC_DATA_MASK;
448				wn_lradc_report_raw(lradc, raw);
449			}
450			handled = true;
451		}
452	
453		/* 写 1 清中断状态位（W1C）。必须在处理完之后清，否则会丢事件 */
454		wn_lradc_write(lradc, LRADC_INTS, ints);
455	
456		return handled ? IRQ_HANDLED : IRQ_NONE;
457	}
458	
459	/* ------------------------------------------------------------------ */
460	/* ADC 使能 / 关闭                                                     */
461	/* ------------------------------------------------------------------ */
462	
463	/*
464	 * 使能 ADC。
465	 *
466	 * 寄存器取值与 mainline 一致：
467	 *   FIRST_CONVERT_DLY(2)  首次转换延时
468	 *   LEVELA_B_CNT(1)       电平判决次数
469	 *   HOLD_EN(1)            按住不放时重复上报
470	 *   SAMPLE_RATE(0)        250 Hz / 4 ms
471	 *   ENABLE(1)
472	 *
473	 * 注意：本板实测初始 CTRL=0x01000168，其中 FIRST_CONVERT_DLY 为 1 而非 2，
474	 * 且 ENABLE=0。这里按 mainline 的 2 写入，probe 后会把实测值打到日志里，
475	 * 便于对照「我确实改动了硬件」。
476	 */
477	static int wn_lradc_enable(struct wn_lradc *lradc)
478	{
479		int ret;
480	
481		ret = clk_prepare_enable(lradc->clk);
482		if (ret) {
483			dev_err(lradc->dev, "clk_prepare_enable failed: %d\n", ret);
484			return ret;
485		}
486	
487		wn_lradc_write(lradc, LRADC_CTRL,
488			       FIRST_CONVERT_DLY(2) | LEVELA_B_CNT(1) | HOLD_EN(1) |
489			       SAMPLE_RATE(LRADC_SAMPLE_RATE_VAL) | ENABLE(1));
490		wn_lradc_write(lradc, LRADC_INTC, CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ);
491	
492		lradc->is_open = true;
493		return 0;
494	}
495	
496	static void wn_lradc_disable(struct wn_lradc *lradc)
497	{
498		/*
499		 * 幂等：probe 失败路径上可能还没 enable 过就跳到这里，
500		 * 直接 clk_disable_unprepare() 会触发内核的时钟引用计数告警。
501		 */
502		if (!lradc->is_open)
503			return;
504	
505		/* 关中断使能，再关 ADC，最后关时钟。顺序反了会留下挂起中断 */
506		wn_lradc_write(lradc, LRADC_INTC, 0);
507		wn_lradc_write(lradc, LRADC_CTRL,
508			       FIRST_CONVERT_DLY(2) | LEVELA_B_CNT(1) | HOLD_EN(1) |
509			       SAMPLE_RATE(2));	/* ENABLE(0) */
510		clk_disable_unprepare(lradc->clk);
511		lradc->is_open = false;
512	}
513	
514	/* ------------------------------------------------------------------ */
515	/* input 子系统（L3）                                                   */
516	/* ------------------------------------------------------------------ */
517	
518	/*
519	 * @input->open / @input->close 是内核对「有没有用户态在听」这件事的
520	 * 唯一权威通知。evdev 被第一次 open 时调 open，最后一个 fd 关闭时调 close。
521	 *
522	 * 所以省电逻辑放在这里，而不是 probe/remove 里：
523	 *   probe   → 注册设备、申请中断，但 ADC 不转换（is_open = false）
524	 *   有人 open /dev/input/eventN → ADC 开始转换，中断通路激活
525	 *   所有人关闭           → ADC 停止，时钟关闭，板子回到零功耗
526	 *
527	 * 两个回调都在进程上下文执行（持 input->mutex），允许睡眠，
528	 * 因此可以直接 clk_prepare_enable()。
529	 */
530	static int wn_lradc_input_open(struct input_dev *input)
531	{
532		struct wn_lradc *lradc = input_get_drvdata(input);
533		int ret;
534	
535		ret = wn_lradc_enable(lradc);
536		if (ret) {
537			dev_err(lradc->dev, "enable on open failed: %d\n", ret);
538			return ret;
539		}
540	
541		dev_info(lradc->dev, "evdev opened: adc enabled\n");
542		return 0;
543	}
544	
545	static void wn_lradc_input_close(struct input_dev *input)
546	{
547		struct wn_lradc *lradc = input_get_drvdata(input);
548	
549		wn_lradc_disable(lradc);
550		dev_info(lradc->dev, "evdev closed: adc disabled\n");
551	}
552	
553	/*
554	 * 分配并注册 input 设备。
555	 *
556	 * 用 devm_input_allocate_device() 而不是 input_allocate_device()：
557	 * 前者挂 devres，驱动解绑时自动 input_unregister_device()，
558	 * 不会漏掉 error path 上的释放（这类泄漏在真实驱动里很常见）。
559	 */
560	static int wn_lradc_input_init(struct wn_lradc *lradc)
561	{
562		struct device *dev = lradc->dev;
563		struct input_dev *input;
564		u32 i;
565	
566		input = devm_input_allocate_device(dev);
567		if (!input)
568			return -ENOMEM;
569	
570		input->name = "weaknet-lradc-keys";
571		input->phys = "weaknet-lradc/input0";
572		input->id.bustype = BUS_HOST;
573		input->dev.parent = dev;
574	
575		/*
576		 * 能力位：EV_KEY 表示「我能发按键」，EV_SYN 表示「我会发同步包」。
577		 * 少了 EV_SYN，用户态 evdev 客户端会一直等不到事件边界，看起来像丢键。
578		 */
579		set_bit(EV_KEY, input->evbit);
580		set_bit(EV_SYN, input->evbit);
581	
582		/* 每个解析出来的按键都要显式声明能力，否则内核拒绝上报该键码 */
583		for (i = 0; i < lradc->nr_keys; i++) {
584			set_bit(lradc->keys[i].keycode, input->keybit);
585			dev_info(dev, "declare key%u: code %u at %u mV (raw ~%u)\n",
586				 i, lradc->keys[i].keycode,
587				 lradc->keys[i].voltage_mv, lradc->keys[i].raw);
588		}
589	
590		input->open  = wn_lradc_input_open;
591		input->close = wn_lradc_input_close;
592	
593		input_set_drvdata(input, lradc);
594	
595		/*
596		 * input_register_device() 之后 /dev/input/eventN 就出现了，
597		 * 但此时 ADC 还没开始转换——要等用户态 open 才启动。
598		 */
599		if (input_register_device(input)) {
600			dev_err(dev, "input_register_device failed\n");
601			return -ENODEV;
602		}
603	
604		lradc->input = input;
605	
606		dev_info(dev, "input device registered: '%s' (%u keys)\n",
607			 input->name, lradc->nr_keys);
608		return 0;
609	}
