730	static int wn_lradc_dbg_regs_show(struct seq_file *s, void *unused)
731	{
732		struct wn_lradc *lradc = s->private;
733		unsigned long flags;
734		u32 ctrl, intc, ints, d0, d1;
735		u64 n_irq, n_down, n_up, n_unk, n_unm;
736		u32 cur, lraw, lmv;
737	
738		/* 寄存器是硬件状态，直接读，不需要锁 */
739		ctrl = wn_lradc_read(lradc, LRADC_CTRL);
740		intc = wn_lradc_read(lradc, LRADC_INTC);
741		ints = wn_lradc_read(lradc, LRADC_INTS);
742		d0   = wn_lradc_read(lradc, LRADC_DATA0);
743		d1   = wn_lradc_read(lradc, LRADC_DATA1);
744	
745		spin_lock_irqsave(&lradc->lock, flags);
746		n_irq  = lradc->stat_irq;
747		n_down = lradc->stat_keydown;
748		n_up   = lradc->stat_keyup;
749		n_unk  = lradc->stat_unknown;
750		n_unm  = lradc->stat_unmatched;
751		cur    = lradc->cur_keycode;
752		lraw   = lradc->last_raw;
753		lmv    = lradc->last_mv;
754		spin_unlock_irqrestore(&lradc->lock, flags);
755	
756		seq_printf(s, "== registers ==\n");
757		seq_printf(s, "  CTRL   [0x%02x] = 0x%08x  (ENABLE=%u, SAMPLE_RATE=%u)\n",
758			   LRADC_CTRL, ctrl, ctrl & 1, (ctrl >> 2) & 0x3);
759		seq_printf(s, "  INTC   [0x%02x] = 0x%08x\n", LRADC_INTC, intc);
760		seq_printf(s, "  INTS   [0x%02x] = 0x%08x\n", LRADC_INTS, ints);
761		seq_printf(s, "  DATA0  [0x%02x] = 0x%08x  (6bit raw=%u, %u mV)\n",
762			   LRADC_DATA0, d0, d0 & LRADC_DATA_MASK,
763			   wn_lradc_raw_to_mv(lradc, d0 & LRADC_DATA_MASK));
764		seq_printf(s, "  DATA1  [0x%02x] = 0x%08x  (6bit raw=%u)\n",
765			   LRADC_DATA1, d1, d1 & LRADC_DATA_MASK);
766	
767		seq_printf(s, "\n== state ==\n");
768		seq_printf(s, "  adc_enabled   : %s\n", lradc->is_open ? "yes" : "no");
769		seq_printf(s, "  cur_keycode   : %u%s\n", cur, cur ? "" : " (idle)");
770		seq_printf(s, "  last_raw/mv   : %u / %u mV\n", lraw, lmv);
771		seq_printf(s, "  vref          : %u mV\n", lradc->vref_mv);
772		seq_printf(s, "  nr_keys       : %u\n", lradc->nr_keys);
773	
774		seq_printf(s, "\n== counters ==\n");
775		seq_printf(s, "  irq           : %llu\n", n_irq);
776		seq_printf(s, "  keydown       : %llu\n", n_down);
777		seq_printf(s, "  keyup         : %llu\n", n_up);
778		seq_printf(s, "  unknown_irq   : %llu\n", n_unk);
779		seq_printf(s, "  unmatched_key : %llu\n", n_unm);
780	
781		seq_printf(s, "\n== keymap ==\n");
782		{
783			u32 i;
784	
785			for (i = 0; i < lradc->nr_keys; i++)
786				seq_printf(s, "  key%-2u %4u mV -> code %-4u (expect raw ~%u)\n",
787					   i, lradc->keys[i].voltage_mv,
788					   lradc->keys[i].keycode,
789					   lradc->keys[i].raw);
790		}
791	
792		return 0;
793	}
