836	/*
837	 * 中断通路自检。
838	 *
839	 * 背景：本板 DT 声明了 5 个按键，但 PCB 上不一定焊接了对应的物理按键。
840	 * 若没有物理按键，KEYDOWN/KEYUP 中断永远不会产生，L2 的「中断真的接通了」
841	 * 就没有直接证据（只有 request_irq 成功这种间接证据）。
842	 *
843	 * 做法：临时往 LRADC_INTC 里加上 CHAN0_DATA_IRQ。ADC 使能后每次转换完成
844	 * 都会置这一位，于是 ISR 必然被调用。等 100 ms 收集到足够的中断次数，
845	 * 再把它关掉，恢复成只有 KEYDOWN|KEYUP 的正常状态。
846	 *
847	 * 这不是「伪造」证据：中断是真的从中断控制器上打进来的，ISR 真的执行了，
848	 * 真的读了 DATA0。它只是让 ADC 在不按键时也持续产生中断而已。
849	 *
850	 * 写入任意内容即触发一次自检。
851	 */
852	static ssize_t wn_lradc_dbg_selftest_write(struct file *file,
853						   const char __user *ubuf,
854						   size_t count, loff_t *ppos)
855	{
856		struct seq_file *s = file->private_data;
857		struct wn_lradc *lradc = s->private;
858		unsigned long flags;
859		u64 before, after;
860		bool was_open;
861		u32 raw;
862		int ret;
863	
864		/*
865		 * L3 之后 ADC 默认不使能（等 evdev open）。但自检必须让 ADC 真的跑起来
866		 * 才能验证中断通路，所以这里临时自己开——测完再恢复原状态。
867		 * 若已有用户态在听（was_open=true），就沿用它的使能状态，不能替它关。
868		 */
869		was_open = lradc->is_open;
870		if (!was_open) {
871			ret = wn_lradc_enable(lradc);
872			if (ret) {
873				dev_err(lradc->dev, "selftest: enable adc failed: %d\n",
874					ret);
875				return ret;
876			}
877		}
878	
879		spin_lock_irqsave(&lradc->lock, flags);
880		before = lradc->stat_irq;
881		lradc->selftest_irqs = 0;
882		lradc->selftest_done = true;
883		spin_unlock_irqrestore(&lradc->lock, flags);
884	
885		/* 打开「转换完成」中断，让 ADC 无键也持续产生中断 */
886		wn_lradc_write(lradc, LRADC_INTC,
887			       CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ | CHAN0_DATA_IRQ);
888	
889		/* 250 Hz 下 100 ms 约 25 次转换，足够证明通路 */
890		msleep(100);
891	
892		/* 关掉自检中断位，恢复正常运行时的掩码 */
893		wn_lradc_write(lradc, LRADC_INTC, CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ);
894	
895		spin_lock_irqsave(&lradc->lock, flags);
896		after = lradc->stat_irq;
897		lradc->selftest_done = false;
898		raw = lradc->selftest_raw;
899		spin_unlock_irqrestore(&lradc->lock, flags);
900	
901		dev_info(lradc->dev,
902			 "selftest: %llu irqs in 100ms (total %llu->%llu), last raw=%u\n",
903			 after - before, before, after, raw);
904	
905		if (after == before)
906			dev_err(lradc->dev,
907				"selftest FAILED: no interrupt observed, ISR path is dead\n");
908		else
909			dev_info(lradc->dev, "selftest PASSED: ISR path is alive\n");
910	
911		/* 恢复：如果使能是我们自己加的，就自己关掉，别改变原有状态 */
912		if (!was_open)
913			wn_lradc_disable(lradc);
914	
915		return count;
916	}
917	
918	static int wn_lradc_dbg_selftest_show(struct seq_file *s, void *unused)
919	{
920		struct wn_lradc *lradc = s->private;
921		unsigned long flags;
922		u64 total, self, raw;
923		bool done;
924	
925		spin_lock_irqsave(&lradc->lock, flags);
926		total = lradc->stat_irq;
927		self  = lradc->selftest_irqs;
928		raw   = lradc->selftest_raw;
929		done  = lradc->selftest_done;
930		spin_unlock_irqrestore(&lradc->lock, flags);
931	
932		seq_printf(s, "adc_enabled : %s\n", lradc->is_open ? "yes" : "no");
933		seq_printf(s, "irq_total   : %llu\n", total);
934		seq_printf(s, "selftest_irqs: %llu\n", self);
935		seq_printf(s, "selftest_raw : %llu\n", raw);
936		seq_printf(s, "running     : %s\n", done ? "yes" : "no");
937		seq_printf(s, "\nwrite anything to this file to run a 100ms self-test\n");
938		return 0;
939	}
940	
941	static int wn_lradc_dbg_selftest_open(struct inode *inode, struct file *file)
942	{
943		return single_open(file, wn_lradc_dbg_selftest_show, inode->i_private);
944	}
945	
946	static const struct file_operations wn_lradc_dbg_selftest_fops = {
947		.owner   = THIS_MODULE,
948		.open    = wn_lradc_dbg_selftest_open,
949		.read    = seq_read,
950		.write   = wn_lradc_dbg_selftest_write,
951		.llseek  = seq_lseek,
952		.release = single_release,
953	};
954	
955	/*
956	 * 原始寄存器读写口（调试专用）。
957	 *
958	 * 写入格式："<偏移> <值>"，两个都是十六进制，例：
959	 *     echo "00 02000141" > /sys/kernel/debug/weaknet_lradc/raw
960	 *
961	 * 用途：本板的 LRADC 在 vendor BSP 里没有驱动，行为只能靠实测确定。
962	 * 有了这个口就能在板端直接扫 CTRL/INTC 的各种组合，不必反复改代码重编译。
963	 * 读回值会同时打到 dmesg，用于确认写入是否真的落到了硬件。
964	 */
965	static ssize_t wn_lradc_dbg_raw_write(struct file *file,
966					      const char __user *ubuf,
967					      size_t count, loff_t *ppos)
968	{
969		struct seq_file *s = file->private_data;
970		struct wn_lradc *lradc = s->private;
971		char buf[64];
972		unsigned int reg, val;
973		u32 readback;
974		int n;
975	
976		if (count >= sizeof(buf))
977			return -EINVAL;
978		if (copy_from_user(buf, ubuf, count))
979			return -EFAULT;
980		buf[count] = '\0';
981	
982		n = sscanf(buf, "%x %x", &reg, &val);
983		if (n != 2)
984			return -EINVAL;
985		/*
986		 * 允许整个 0x100 窗口（4 字节对齐）。
987		 *
988		 * 最初只开放到 DATA1(0x10)，理由是「已知布局就这几个寄存器」。
989		 * 但 A733 的 LRADC 与 mainline sun4i 的同名 IP 行为并不一致：
990		 * CTRL 写入成功、时钟已开、复位已解，DATA0 却始终停在复位值 0x3f。
991		 * 说明还有未知寄存器（或窗口外的模拟控制位）参与使能，
992		 * 必须能扫描整段窗口才能定位。这是调试口存在的意义。
993		 */
994		if (reg > 0xfc || (reg & 0x3))
995			return -EINVAL;
996	
997		wn_lradc_write(lradc, reg, val);
998		readback = wn_lradc_read(lradc, reg);
999	
1000		dev_info(lradc->dev, "raw: reg[0x%02x] <= 0x%08x, readback 0x%08x\n",
1001			 reg, val, readback);
1002	
1003		return count;
1004	}
1005	
1006	static int wn_lradc_dbg_raw_show(struct seq_file *s, void *unused)
1007	{
1008		struct wn_lradc *lradc = s->private;
1009	
1010		u32 off, val;
1011	
1012		seq_printf(s, "usage: echo \"<offset_hex> <value_hex>\" > raw\n");
1013		seq_printf(s, "regs: 00 CTRL / 04 INTC / 08 INTS / 0c DATA0 / 10 DATA1\n\n");
1014	
1015		seq_printf(s, "CTRL   = 0x%08x\n", wn_lradc_read(lradc, LRADC_CTRL));
1016		seq_printf(s, "INTC   = 0x%08x\n", wn_lradc_read(lradc, LRADC_INTC));
1017		seq_printf(s, "INTS   = 0x%08x\n", wn_lradc_read(lradc, LRADC_INTS));
1018		seq_printf(s, "DATA0  = 0x%08x\n", wn_lradc_read(lradc, LRADC_DATA0));
1019		seq_printf(s, "DATA1  = 0x%08x\n", wn_lradc_read(lradc, LRADC_DATA1));
1020	
1021		/*
1022		 * 全窗口扫描：只打印非零项与已知布局项，避免刷屏。
1023		 * 已知项即使为 0 也打印，便于确认「确实读到了 0」而非越界。
1024		 */
1025		seq_printf(s, "\nfull window 0x00-0xfc (nonzero + known):\n");
1026		for (off = 0; off <= 0xfc; off += 4) {
1027			val = wn_lradc_read(lradc, off);
1028			if (val || off <= LRADC_DATA1)
1029				seq_printf(s, "  [0x%02x] = 0x%08x\n", off, val);
1030		}
1031	
1032		return 0;
1033	}
1034	
1035	static int wn_lradc_dbg_raw_open(struct inode *inode, struct file *file)
1036	{
1037		return single_open(file, wn_lradc_dbg_raw_show, inode->i_private);
1038	}
1039	
1040	static const struct file_operations wn_lradc_dbg_raw_fops = {
1041		.owner   = THIS_MODULE,
1042		.open    = wn_lradc_dbg_raw_open,
1043		.read    = seq_read,
1044		.write   = wn_lradc_dbg_raw_write,
1045		.llseek  = seq_lseek,
1046		.release = single_release,
1047	};
1048	
1049	/*
1050	 * L3 注入口：直接喂一个 raw 值，走完整的「换算 → 匹配 → input 上报」链路。
1051	 *
1052	 * 存在理由（不是玩具）：本板 ADC 从不转换（见文件头「实测边界」），
1053	 * 物理按键永远产生不了中断，L3 就永远拿不到端到端证据。
1054	 * 这个口把硬件那一端短路掉，让上层的匹配、去重、input_report_key、
1055	 * evdev 分发全部真实执行一次，从而可以证明：
1056	 *   - keybit 声明正确（漏声明时内核会丢弃该键码，用户态什么都收不到）
1057	 *   - input_report_key + input_sync 产生了合法的 evdev 事件
1058	 *   - 去重逻辑（同一个键按住不重复上报）成立
1059	 *
1060	 * 写入格式：
1061	 *   echo <raw 0-63> > inject     注入一次按下
1062	 *   echo release    > inject     注入一次抬起
1063	 */
1064	static ssize_t wn_lradc_dbg_inject_write(struct file *file,
1065						 const char __user *ubuf,
1066						 size_t count, loff_t *ppos)
1067	{
1068		struct seq_file *s = file->private_data;
1069		struct wn_lradc *lradc = s->private;
1070		char buf[32];
1071		unsigned int raw;
1072		bool busy;
1073	
1074		if (count >= sizeof(buf))
1075			return -EINVAL;
1076		if (copy_from_user(buf, ubuf, count))
1077			return -EFAULT;
1078		buf[count] = '\0';
1079	
1080		if (sysfs_streq(buf, "release")) {
1081			wn_lradc_release(lradc);
1082			return count;
1083		}
1084	
1085		if (sscanf(buf, "%u", &raw) != 1) {
1086			dev_warn(lradc->dev,
1087				 "inject: usage \"<raw 0-63>\" or \"release\"\n");
1088			return -EINVAL;
1089		}
1090	
1091		if (raw > LRADC_FULL_SCALE) {
1092			dev_warn(lradc->dev, "inject: raw %u out of range 0-%u\n",
1093				 raw, LRADC_FULL_SCALE);
1094			return -EINVAL;
1095		}
1096	
1097		/*
1098		 * 若已有键按着（cur_keycode 非 0），先抬起再按新键，
1099		 * 模拟真实的「手指从 A 键滑到 B 键」——用户态会看到 release+press 一对事件。
1100		 * 不做这一步的话第二次注入会被去重逻辑吞掉，看起来像「注入无效」。
1101		 */
1102		spin_lock_irq(&lradc->lock);
1103		busy = (lradc->cur_keycode != 0);
1104		spin_unlock_irq(&lradc->lock);
1105	
1106		if (busy)
1107			wn_lradc_release(lradc);
1108	
1109		wn_lradc_report_raw(lradc, raw);
1110	
1111		return count;
1112	}
1113	
1114	static int wn_lradc_dbg_inject_show(struct seq_file *s, void *unused)
1115	{
1116		struct wn_lradc *lradc = s->private;
1117		unsigned long flags;
1118		u32 last_raw, cur;
1119		int i;
1120	
1121		spin_lock_irqsave(&lradc->lock, flags);
1122		last_raw = lradc->last_raw;
1123		cur = lradc->cur_keycode;
1124		spin_unlock_irqrestore(&lradc->lock, flags);
1125	
1126		seq_puts(s, "usage: echo \"<raw 0-63>\" > inject   (inject a key press)\n");
1127		seq_puts(s, "       echo release          > inject   (inject a key release)\n\n");
1128		seq_printf(s, "input device : %s\n",
1129			   lradc->input ? "registered" : "absent");
1130		seq_printf(s, "cur_keycode  : %u\n", cur);
1131		seq_printf(s, "last_raw     : %u (mv %u)\n", last_raw,
1132			   wn_lradc_raw_to_mv(lradc, last_raw));
1133		seq_puts(s, "\nraw -> voltage -> keycode table:\n");
1134		for (i = 0; i < lradc->nr_keys; i++)
1135			seq_printf(s, "  raw %2u = %4u mV -> code %u\n",
1136				   lradc->keys[i].raw,
1137				   lradc->keys[i].voltage_mv,
1138				   lradc->keys[i].keycode);
1139		return 0;
1140	}
1141	
1142	static int wn_lradc_dbg_inject_open(struct inode *inode, struct file *file)
1143	{
1144		return single_open(file, wn_lradc_dbg_inject_show, inode->i_private);
1145	}
1146	
1147	static const struct file_operations wn_lradc_dbg_inject_fops = {
1148		.owner   = THIS_MODULE,
1149		.open    = wn_lradc_dbg_inject_open,
1150		.read    = seq_read,
1151		.write   = wn_lradc_dbg_inject_write,
1152		.llseek  = seq_lseek,
1153		.release = single_release,
1154	};
1155	
1156	static const struct file_operations wn_lradc_dbg_sample_fops = {
1157		.owner   = THIS_MODULE,
1158		.open    = wn_lradc_dbg_sample_open,
1159		.read    = seq_read,
1160		.write   = wn_lradc_dbg_sample_write,
1161		.llseek  = seq_lseek,
1162		.release = single_release,
1163	};
1164	
1165	static void wn_lradc_debugfs_init(struct wn_lradc *lradc)
1166	{
1167		lradc->dbg_dir = debugfs_create_dir("weaknet_lradc", NULL);
1168		if (IS_ERR_OR_NULL(lradc->dbg_dir)) {
1169			lradc->dbg_dir = NULL;
1170			dev_warn(lradc->dev, "debugfs unavailable, skip\n");
1171			return;
1172		}
1173	
1174		debugfs_create_file("regs", 0444, lradc->dbg_dir, lradc,
1175				    &wn_lradc_dbg_regs_fops);
1176		debugfs_create_file("sample", 0644, lradc->dbg_dir, lradc,
1177				    &wn_lradc_dbg_sample_fops);
1178		debugfs_create_file("selftest", 0644, lradc->dbg_dir, lradc,
1179				    &wn_lradc_dbg_selftest_fops);
1180		debugfs_create_file("raw", 0644, lradc->dbg_dir, lradc,
1181				    &wn_lradc_dbg_raw_fops);
1182		debugfs_create_file("inject", 0644, lradc->dbg_dir, lradc,
1183				    &wn_lradc_dbg_inject_fops);
1184	}
1185	
1186	/* ------------------------------------------------------------------ */
1187	/* probe / remove                                                      */
1188	/* ------------------------------------------------------------------ */
1189	
1190	static int wn_lradc_probe(struct platform_device *pdev)
1191	{
1192		struct device *dev = &pdev->dev;
1193		struct wn_lradc *lradc;
1194		u32 ctrl_before;
1195		int ret;
1196	
1197		lradc = devm_kzalloc(dev, sizeof(*lradc), GFP_KERNEL);
1198		if (!lradc)
1199			return -ENOMEM;
1200	
1201		lradc->dev = dev;
1202		spin_lock_init(&lradc->lock);
1203		platform_set_drvdata(pdev, lradc);
1204	
1205		/* ---- 1. 映射寄存器 ---- */
1206		lradc->base = devm_platform_ioremap_resource(pdev, 0);
1207		if (IS_ERR(lradc->base)) {
1208			ret = PTR_ERR(lradc->base);
1209			dev_err(dev, "ioremap failed: %d\n", ret);
1210			return ret;
1211		}
1212		dev_info(dev, "mapped registers at %pR\n",
1213			 platform_get_resource(pdev, IORESOURCE_MEM, 0));
1214	
1215		/* ---- 2. 参考电压 + 按键表（先解析，失败就不用申请资源了）---- */
1216		lradc->vref_mv = wn_lradc_parse_vref(dev);
1217	
1218		ret = wn_lradc_parse_keymap(lradc);
1219		if (ret)
1220			return ret;
1221	
1222		/* ---- 3. 时钟 ---- */
1223		/*
1224		 * DT 里没有 clock-names，只有一个 clocks 项，
1225		 * 所以 devm_clk_get(dev, NULL) 取第一个（也是唯一一个）。
1226		 */
1227		lradc->clk = devm_clk_get(dev, NULL);
1228		if (IS_ERR(lradc->clk)) {
1229			ret = PTR_ERR(lradc->clk);
1230			if (ret == -EPROBE_DEFER)
1231				return ret;
1232			dev_err(dev, "get clock failed: %d\n", ret);
1233			return ret;
1234		}
1235		dev_info(dev, "clock rate = %lu Hz\n", clk_get_rate(lradc->clk));
1236	
1237		/* ---- 4. 复位（可选，DT 里没有 reset-names）---- */
1238		lradc->rst = devm_reset_control_get_optional_exclusive(dev, NULL);
1239		if (IS_ERR(lradc->rst)) {
1240			ret = PTR_ERR(lradc->rst);
1241			if (ret == -EPROBE_DEFER)
1242				return ret;
1243			dev_warn(dev, "reset control unavailable: %d, continue\n", ret);
1244			lradc->rst = NULL;
1245		}
1246		if (lradc->rst) {
1247			ret = reset_control_reset(lradc->rst);
1248			if (ret) {
1249				ret = reset_control_deassert(lradc->rst);
1250				if (ret)
1251					dev_warn(dev, "reset deassert failed: %d\n", ret);
1252			}
1253			dev_info(dev, "reset controller deasserted\n");
1254		}
1255	
1256		/* ---- 5. 记录使能前的寄存器原值（作为「我真的动过硬件」的证据）---- */
1257		ctrl_before = wn_lradc_read(lradc, LRADC_CTRL);
1258		dev_info(dev, "CTRL before enable = 0x%08x\n", ctrl_before);
1259	
1260		/* ---- 6. 中断必须先注册 ---- */
1261		/*
1262		 * 顺序很重要：INTC 里的中断使能位一写下去，硬件就可能立刻拉高 IRQ 线。
1263		 * 如果先 enable(ADC) 再 request_irq()，中间这段窗口期的中断没有 handler，
1264		 * 内核会记成 spurious IRQ；中断线是电平触发时还会一直挂着直到有人清。
1265		 * 所以这里先注册 handler，再用 wn_lradc_enable() 去开硬件中断。
1266		 */
1267		lradc->irq = platform_get_irq(pdev, 0);
1268		if (lradc->irq < 0) {
1269			ret = lradc->irq;
1270			dev_err(dev, "get irq failed: %d\n", ret);
1271			goto err_disable;
1272		}
1273	
1274		ret = devm_request_irq(dev, lradc->irq, wn_lradc_irq, 0,
1275				       "weaknet-lradc", lradc);
1276		if (ret) {
1277			dev_err(dev, "request_irq(%d) failed: %d\n", lradc->irq, ret);
1278			goto err_disable;
1279		}
1280		dev_info(dev, "irq %d registered\n", lradc->irq);
1281	
1282		/* ---- 7. input 设备（L3）---- */
1283		/*
1284		 * 必须在 request_irq() 之后：input_register_device() 一返回，
1285		 * /dev/input/eventN 立刻可被 open，而 open 回调会使能 ADC 并打中断使能位。
1286		 * 如果那时 handler 还没注册，电平中断会一直挂着直到内核判定 spurious。
1287		 *
1288		 * 注意这里不调用 wn_lradc_enable()——ADC 保持关闭，
1289		 * 直到真有进程 open evdev。这是键盘类驱动的标准省电语义。
1290		 */
1291		ret = wn_lradc_input_init(lradc);
1292		if (ret) {
1293			dev_err(dev, "input init failed: %d\n", ret);
1294			goto err_disable;
1295		}
1296	
1297		/* ---- 8. debugfs ---- */
1298		wn_lradc_debugfs_init(lradc);
1299	
1300		dev_info(dev, "probe done: %u keys, vref %u mV, sample %u Hz\n",
1301			 lradc->nr_keys, lradc->vref_mv,
1302			 LRADC_SAMPLE_RATE_VAL == 0 ? 250 :
1303			 LRADC_SAMPLE_RATE_VAL == 1 ? 125 :
1304			 LRADC_SAMPLE_RATE_VAL == 2 ? 62 : 31);
1305		dev_info(dev, "CTRL after probe = 0x%08x (ENABLE=%u, adc idle until evdev open)\n",
1306			 wn_lradc_read(lradc, LRADC_CTRL),
1307			 wn_lradc_read(lradc, LRADC_CTRL) & 1);
1308	
1309		return 0;
1310	
1311	err_disable:
1312		wn_lradc_disable(lradc);
1313		return ret;
1314	}
1315	
1316	static int wn_lradc_remove(struct platform_device *pdev)
1317	{
1318		struct wn_lradc *lradc = platform_get_drvdata(pdev);
1319	
1320		/*
1321		 * devm 会自动回收 irq / ioremap / clk 引用，
1322		 * 但 ADC 使能与时钟 enable 计数是我们手动加的，必须手动关。
1323		 */
1324		wn_lradc_disable(lradc);
1325	
1326		debugfs_remove_recursive(lradc->dbg_dir);
1327		lradc->dbg_dir = NULL;
1328	
1329		dev_info(lradc->dev, "removed: irq=%llu keydown=%llu keyup=%llu\n",
1330			 lradc->stat_irq, lradc->stat_keydown, lradc->stat_keyup);
1331	
1332		return 0;
1333	}
1334	
1335	/* ------------------------------------------------------------------ */
1336	/* 驱动注册                                                            */
1337	/* ------------------------------------------------------------------ */
1338	
1339	static const struct of_device_id wn_lradc_of_match[] = {
1340		/*
1341		 * 本板 DT：compatible = "allwinner,keyboard_1350mv";
1342		 * 这个字符串在 mainline 里不存在，是 Allwinner BSP 的私有约定。
1343		 */
1344		{ .compatible = "allwinner,keyboard_1350mv" },
1345		{ /* sentinel */ }
1346	};
1347	MODULE_DEVICE_TABLE(of, wn_lradc_of_match);
1348	
1349	static struct platform_driver wn_lradc_driver = {
1350		.probe  = wn_lradc_probe,
1351		.remove = wn_lradc_remove,
1352		.driver = {
1353			.name           = "weaknet-lradc-keys",
1354			.of_match_table = wn_lradc_of_match,
1355		},
1356	};
1357	module_platform_driver(wn_lradc_driver);
1358	
1359	MODULE_AUTHOR("tanqf");
1360	MODULE_DESCRIPTION("WeakNet LRADC keypad driver for Allwinner A733 (sun60iw2p1)");
1361	MODULE_LICENSE("GPL");
1362	MODULE_VERSION("0.1.0");
1363

