131	/* LRADC_CTRL 位域 */
132	#define FIRST_CONVERT_DLY(x)	((x) << 24)	/* 8 bits */
133	#define CHAN_SELECT(x)		((x) << 22)	/* 2 bits */
134	#define CONTINUE_TIME_SEL(x)	((x) << 16)	/* 4 bits */
135	#define KEY_MODE_SEL(x)		((x) << 12)	/* 2 bits */
136	#define LEVELA_B_CNT(x)		((x) << 8)	/* 4 bits */
137	#define HOLD_KEY_EN(x)		((x) << 7)
138	#define HOLD_EN(x)		((x) << 6)
139	#define LEVELB_VOL(x)		((x) << 4)	/* 2 bits */
140	#define SAMPLE_RATE(x)		((x) << 2)	/* 2 bits */
141	#define ENABLE(x)		((x) << 0)
