143	/* LRADC_INTC / LRADC_INTS 位域（本驱动只用通道 0） */
144	#define CHAN0_KEYUP_IRQ		BIT(4)
145	#define CHAN0_ALRDY_HOLD_IRQ	BIT(3)
146	#define CHAN0_HOLD_IRQ		BIT(2)
147	#define CHAN0_KEYDOWN_IRQ	BIT(1)
148	#define CHAN0_DATA_IRQ		BIT(0)
