611	/* ------------------------------------------------------------------ */
612	/* DT 解析                                                             */
613	/* ------------------------------------------------------------------ */
614	
615	/*
616	 * 从 compatible 字符串里取参考电压，形如 "allwinner,keyboard_1350mv"。
617	 * 取不到就返回默认值。这是本板 BSP 的私有约定，mainline 没有。
618	 */
619	static u32 wn_lradc_parse_vref(struct device *dev)
620	{
621		const char *compat;
622		u32 mv = LRADC_DEFAULT_VREF_MV;
623		int ret;
624	
625		ret = of_property_read_string(dev->of_node, "compatible", &compat);
626		if (ret)
627			return mv;
628	
629		/*
630		 * 在字符串里找 "1350mv" 这样的片段。不用 sscanf 是因为
631		 * compatible 可能带多个逗号分隔项，直接定位数字更稳。
632		 */
633		while (*compat) {
634			if (*compat >= '0' && *compat <= '9') {
635				u32 val = 0;
636				const char *p = compat;
637	
638				while (*p >= '0' && *p <= '9') {
639					val = val * 10 + (*p - '0');
640					p++;
641				}
642				/* 紧跟 "mv" 才认，避免把 "a733" 之类误当电压 */
643				if (p[0] == 'm' && p[1] == 'v') {
644					if (val >= 500 && val <= 5000)
645						mv = val;
646					break;
647				}
648				compat = p;
649				continue;
650			}
651			compat++;
652		}
653	
654		return mv;
655	}
656	
657	/*
658	 * 解析按键表。
659	 *
660	 * 本板 DT 格式（与 mainline 完全不同）：
661	 *     key_cnt = <5>;
662	 *     key0 = <210 115>;      电压 210 mV，键码 115
663	 *     key1 = <410 114>;
664	 *     ...
665	 *
666	 * 返回 0 表示成功；负值表示失败。
667	 */
668	static int wn_lradc_parse_keymap(struct wn_lradc *lradc)
669	{
670		struct device *dev = lradc->dev;
671		struct device_node *np = dev->of_node;
672		u32 key_cnt = 0;
673		u32 i;
674		int ret;
675	
676		ret = of_property_read_u32(np, "key_cnt", &key_cnt);
677		if (ret) {
678			dev_err(dev, "no key_cnt property in DT\n");
679			return -EINVAL;
680		}
681		if (key_cnt == 0) {
682			dev_err(dev, "key_cnt is 0\n");
683			return -EINVAL;
684		}
685		if (key_cnt > LRADC_MAX_KEYS) {
686			dev_warn(dev, "key_cnt %u exceeds max %d, truncating\n",
687				 key_cnt, LRADC_MAX_KEYS);
688			key_cnt = LRADC_MAX_KEYS;
689		}
690	
691		for (i = 0; i < key_cnt; i++) {
692			char prop[16];
693			u32 pair[2];
694	
695			snprintf(prop, sizeof(prop), "key%u", i);
696			ret = of_property_read_u32_array(np, prop, pair, 2);
697			if (ret) {
698				dev_warn(dev, "%s missing or malformed, skipping\n", prop);
699				continue;
700			}
701	
702			lradc->keys[lradc->nr_keys].voltage_mv = pair[0];
703			lradc->keys[lradc->nr_keys].keycode = pair[1];
704			/* 换算成 6bit 期望码值，仅用于日志对照，不参与判定 */
705			lradc->keys[lradc->nr_keys].raw =
706				(pair[0] * LRADC_FULL_SCALE + lradc->vref_mv / 2) /
707				lradc->vref_mv;
708			lradc->nr_keys++;
709		}
710	
711		if (lradc->nr_keys == 0) {
712			dev_err(dev, "no valid key parsed\n");
713			return -EINVAL;
714		}
715	
716		dev_info(dev, "parsed %u keys (vref=%u mV):\n", lradc->nr_keys,
717			 lradc->vref_mv);
718		for (i = 0; i < lradc->nr_keys; i++)
719			dev_info(dev, "  key%u: %u mV -> KEY code %u (expect raw ~%u)\n",
720				 i, lradc->keys[i].voltage_mv, lradc->keys[i].keycode,
721				 lradc->keys[i].raw);
722	
723		return 0;
724	}
