1189	
1190	static int wn_lradc_probe(struct platform_device *pdev)
1191	{
1192		struct device *dev = &pdev->dev;
1193		struct wn_lradc *lradc;
1194		u32 ctrl_before;
1195		int ret;
1196	
1197		lradc = devm_kzalloc(dev, sizeof(*lradc), GFP_KERNEL);
1198		if (!lradc)
1199			return -ENOMEM;
1200	
1201		lradc->dev = dev;
1202		spin_lock_init(&lradc->lock);
1203		platform_set_drvdata(pdev, lradc);
1204	
1205		/* ---- 1. 映射寄存器 ---- */
1206		lradc->base = devm_platform_ioremap_resource(pdev, 0);
1207		if (IS_ERR(lradc->base)) {
1208			ret = PTR_ERR(lradc->base);
1209			dev_err(dev, "ioremap failed: %d\n", ret);
1210			return ret;
1211		}
1212		dev_info(dev, "mapped registers at %pR\n",
1213			 platform_get_resource(pdev, IORESOURCE_MEM, 0));
1214	
1215		/* ---- 2. 参考电压 + 按键表（先解析，失败就不用申请资源了）---- */
1216		lradc->vref_mv = wn_lradc_parse_vref(dev);
1217	
1218		ret = wn_lradc_parse_keymap(lradc);
1219		if (ret)
1220			return ret;
1221	
1222		/* ---- 3. 时钟 ---- */
1223		/*
1224		 * DT 里没有 clock-names，只有一个 clocks 项，
1225		 * 所以 devm_clk_get(dev, NULL) 取第一个（也是唯一一个）。
1226		 */
1227		lradc->clk = devm_clk_get(dev, NULL);
1228		if (IS_ERR(lradc->clk)) {
1229			ret = PTR_ERR(lradc->clk);
1230			if (ret == -EPROBE_DEFER)
1231				return ret;
1232			dev_err(dev, "get clock failed: %d\n", ret);
1233			return ret;
1234		}
1235		dev_info(dev, "clock rate = %lu Hz\n", clk_get_rate(lradc->clk));
1236	
1237		/* ---- 4. 复位（可选，DT 里没有 reset-names）---- */
1238		lradc->rst = devm_reset_control_get_optional_exclusive(dev, NULL);
1239		if (IS_ERR(lradc->rst)) {
1240			ret = PTR_ERR(lradc->rst);
1241			if (ret == -EPROBE_DEFER)
1242				return ret;
1243			dev_warn(dev, "reset control unavailable: %d, continue\n", ret);
1244			lradc->rst = NULL;
1245		}
1246		if (lradc->rst) {
1247			ret = reset_control_reset(lradc->rst);
1248			if (ret) {
1249				ret = reset_control_deassert(lradc->rst);
1250				if (ret)
1251					dev_warn(dev, "reset deassert failed: %d\n", ret);
1252			}
1253			dev_info(dev, "reset controller deasserted\n");
1254		}
1255	
1256		/* ---- 5. 记录使能前的寄存器原值（作为「我真的动过硬件」的证据）---- */
1257		ctrl_before = wn_lradc_read(lradc, LRADC_CTRL);
1258		dev_info(dev, "CTRL before enable = 0x%08x\n", ctrl_before);
1259	
1260		/* ---- 6. 中断必须先注册 ---- */
1261		/*
1262		 * 顺序很重要：INTC 里的中断使能位一写下去，硬件就可能立刻拉高 IRQ 线。
1263		 * 如果先 enable(ADC) 再 request_irq()，中间这段窗口期的中断没有 handler，
1264		 * 内核会记成 spurious IRQ；中断线是电平触发时还会一直挂着直到有人清。
1265		 * 所以这里先注册 handler，再用 wn_lradc_enable() 去开硬件中断。
1266		 */
1267		lradc->irq = platform_get_irq(pdev, 0);
1268		if (lradc->irq < 0) {
1269			ret = lradc->irq;
1270			dev_err(dev, "get irq failed: %d\n", ret);
1271			goto err_disable;
1272		}
1273	
1274		ret = devm_request_irq(dev, lradc->irq, wn_lradc_irq, 0,
1275				       "weaknet-lradc", lradc);
1276		if (ret) {
1277			dev_err(dev, "request_irq(%d) failed: %d\n", lradc->irq, ret);
1278			goto err_disable;
1279		}
1280		dev_info(dev, "irq %d registered\n", lradc->irq);
1281	
1282		/* ---- 7. input 设备（L3）---- */
1283		/*
1284		 * 必须在 request_irq() 之后：input_register_device() 一返回，
1285		 * /dev/input/eventN 立刻可被 open，而 open 回调会使能 ADC 并打中断使能位。
1286		 * 如果那时 handler 还没注册，电平中断会一直挂着直到内核判定 spurious。
1287		 *
1288		 * 注意这里不调用 wn_lradc_enable()——ADC 保持关闭，
1289		 * 直到真有进程 open evdev。这是键盘类驱动的标准省电语义。
1290		 */
1291		ret = wn_lradc_input_init(lradc);
1292		if (ret) {
1293			dev_err(dev, "input init failed: %d\n", ret);
1294			goto err_disable;
1295		}
1296	
1297		/* ---- 8. debugfs ---- */
1298		wn_lradc_debugfs_init(lradc);
1299	
1300		dev_info(dev, "probe done: %u keys, vref %u mV, sample %u Hz\n",
1301			 lradc->nr_keys, lradc->vref_mv,
1302			 LRADC_SAMPLE_RATE_VAL == 0 ? 250 :
1303			 LRADC_SAMPLE_RATE_VAL == 1 ? 125 :
1304			 LRADC_SAMPLE_RATE_VAL == 2 ? 62 : 31);
1305		dev_info(dev, "CTRL after probe = 0x%08x (ENABLE=%u, adc idle until evdev open)\n",
1306			 wn_lradc_read(lradc, LRADC_CTRL),
1307			 wn_lradc_read(lradc, LRADC_CTRL) & 1);
1308	
1309		return 0;
1310	
1311	err_disable:
1312		wn_lradc_disable(lradc);
1313		return ret;
1314	}
1315	
1316	static int wn_lradc_remove(struct platform_device *pdev)
1317	{
1318		struct wn_lradc *lradc = platform_get_drvdata(pdev);
1319	
1320		/*
1321		 * devm 会自动回收 irq / ioremap / clk 引用，
1322		 * 但 ADC 使能与时钟 enable 计数是我们手动加的，必须手动关。
1323		 */
1324		wn_lradc_disable(lradc);
1325	
1326		debugfs_remove_recursive(lradc->dbg_dir);
1327		lradc->dbg_dir = NULL;
1328	
1329		dev_info(lradc->dev, "removed: irq=%llu keydown=%llu keyup=%llu\n",
1330			 lradc->stat_irq, lradc->stat_keydown, lradc->stat_keyup);
1331	
1332		return 0;
1333	}
