cd /home/ubuntu/.claude/projects/-home-ubuntu------AI-powered-Network-Diagnostics
for f in 2aa5c2bc-a012-42cd-973c-2b7d37b5c89a 711c74ff-b1d0-42ad-a72f-af85f7ba2d16 9eafcbb0-6931-4d46-87dd-b145bfc9d9a4; do
  echo "===== $f ====="
  ls -l --time-style=+%Y-%m-%d\ %H:%M $f.jsonl | awk '{print "  mtime:",$6,$7,"  size:",$5}'
  python3 - "$f.jsonl" <<'PY'
import sys, json
path = sys.argv[1]
writes = 0
mentions = 0
first_write_ts = None
for line in open(path, encoding='utf-8', errors='replace'):
    if '驱动面能力引入与业务融合方案' not in line:
        continue
    mentions += 1
    try:
        d = json.loads(line)
    except Exception:
        continue
    msg = d.get('message') or {}
    content = msg.get('content')
    if not isinstance(content, list):
        continue
    for c in content:
        if isinstance(c, dict) and c.get('type') == 'tool_use':
            inp = json.dumps(c.get('input', {}), ensure_ascii=False)
            if '驱动面能力引入与业务融合方案' in inp and c.get('name') in ('Write', 'Edit', 'NotebookEdit'):
                writes += 1
                if not first_write_ts:
                    first_write_ts = d.get('timestamp')
print(f"  提到该名: {mentions} 行 | Write/Edit 命中: {writes} | 首次写入: {first_write_ts}")
PY
done
